// Cache-aside read path with a short TTL
async function getProduct(id) {
  const key = `product:${id}`;
  const cached = await redis.get(key);
  if (cached) return JSON.parse(cached); // cache hit

  const product = await dbReplica.query(
    'SELECT * FROM products WHERE id = $1', [id]
  );
  await redis.set(key, JSON.stringify(product), 'EX', 300); // 5 min TTL
  return product;
}

// Single-flight: only one caller recomputes a missing key
async function getWithLock(key, loader, ttl = 300) {
  const cached = await redis.get(key);
  if (cached) return JSON.parse(cached);

  const lockKey = `lock:${key}`;
  const gotLock = await redis.set(lockKey, '1', 'NX', 'EX', 10);
  if (!gotLock) {
    await sleep(50);              // let the leader populate
    return getWithLock(key, loader, ttl);
  }
  try {
    const value = await loader(); // single DB hit
    const jitter = Math.floor(Math.random() * 60);
    await redis.set(key, JSON.stringify(value), 'EX', ttl + jitter);
    return value;
  } finally {
    await redis.del(lockKey);
  }
}

// Consistent hashing keeps most keys put when a node is added
function pickShard(key, ring) {
  const h = hash(key);
  // find the first node clockwise on the ring
  for (const node of ring) {       // ring sorted by token
    if (h <= node.token) return node.id;
  }
  return ring[0].id;               // wrap around
}

// Fast write path: persist + publish, return immediately
async function checkout(req, res) {
  const order = await db.orders.insert({ ...req.body, status: 'PENDING' });
  await queue.publish('order.created', {
    orderId: order.id,
    idempotencyKey: order.id // consumers dedupe on this
  });
  res.status(202).json({ orderId: order.id, status: 'PENDING' });
}

async function charge(req, res) {
  const key = req.headers['idempotency-key'];
  return db.tx(async (t) => {
    const existing = await t.oneOrNone(
      'SELECT response FROM idempotency WHERE key=$1', [key]
    );
    if (existing) return res.json(existing.response); // replay

    const result = await paymentGateway.charge(req.body);
    await t.none(
      'INSERT INTO idempotency(key, response) VALUES($1,$2)',
      [key, result] // unique constraint on key blocks dup inserts
    );
    res.json(result);
  });
}

const ALPHABET = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';

function encodeBase62(id) {
  let s = '';
  do {
    s = ALPHABET[id % 62] + s;
    id = Math.floor(id / 62);
  } while (id > 0);
  return s; // e.g. id 125 -> '21'
}

async function createShortUrl(longUrl) {
  const id = await counter.next();      // globally unique id
  const key = encodeBase62(id);
  await kv.put(key, { longUrl });
  return `https://sho.rt/${key}`;
}

// Dedupe + enqueue per enabled channel
async function notify(event) {
  const dedupeKey = `notif:${event.userId}:${event.id}`;
  const fresh = await redis.set(dedupeKey, '1', 'NX', 'EX', 86400);
  if (!fresh) return; // already processed -> no duplicate

  const prefs = await getPreferences(event.userId);
  for (const channel of prefs.enabledChannels) {
    await queue.publish(`notify.${channel}`, {
      userId: event.userId,
      payload: render(event, channel),
      idempotencyKey: `${dedupeKey}:${channel}`
    });
  }
}
